var amount = 300;

var mesh = scene.children[ 0 ];
mesh.visible = false;

var instances = new THREE.InstancedMesh( mesh.geometry, mesh.material, amount );
scene.add( instances );

var transform = new THREE.Object3D();

function update( event ) {

	var time = event.time / 2000;

	for ( var i = 0; i < amount; i ++ ) {

		var theta2 = ( i / amount ) * Math.PI * 2; 
		var theta = ( i / amount ) * ( Math.sin( time / 2.1563 ) + Math.cos( time / 2.8745 ) ) * 2;

		transform.position.y = ( i / 30 ) - 5;

		transform.position.x = Math.sin( theta + time ) * Math.sin( theta * 0.5 + time * 1.345 )
			* Math.cos( theta + time * 1.768 ) * Math.sin( theta2 ) * 1.5;

		transform.position.z = Math.cos( theta + time ) * Math.cos( theta * 0.5 + time * 1.345 )
			* Math.cos( theta + time * 2.768 ) * Math.sin( theta2 ) * 1.5;

		transform.rotation.y = Math.cos( theta * 2 + time ) * Math.sin( theta + time * 1.345 )
			* Math.sin( theta * 0.5 + time * 0.768 ) * 2;

		var scale = 2 + Math.sin( theta + time ) * Math.cos( theta + time * 0.768 )
			* Math.sin( theta + time * 1.768 ) * Math.sin( theta2 );

		transform.scale.x = scale;
		transform.scale.z = scale;

		transform.updateMatrix();

		instances.setMatrixAt( i, transform.matrix );

	}

	instances.instanceMatrix.needsUpdate = true;

	scene.rotation.z = - time / 10;

}

